    var allCountries = ALL_COUNTRIES.slice();
    Object.keys(countryCounts).forEach(function(c){
      if (allCountries.indexOf(c) === -1) allCountries.push(c);
    });
    allCountries.sort();

    document.getElementById("im-f-dept").innerHTML='<option value="">All departments</option>'+depts.map(function(d){return'<option value="'+esc(d)+'">'+esc(d)+'</option>';}).join("");

    // ── FIX: Pin "Global" to top, then countries with roles, then rest ──
    var globalCount  = countryCounts["Global"] || 0;
    var withRoles    = allCountries.filter(function(x){ return (countryCounts[x]||0) > 0 && x !== "Global"; });
    var withoutRoles = allCountries.filter(function(x){ return !countryCounts[x] && x !== "Global"; });
    buildCountryList(globalCount, withRoles, withoutRoles, countryCounts, "");

    refreshStateDropdown("");

    document.getElementById("im-f-lang").innerHTML=
      '<option value="">Pick language</option>'
      +'<option value="">All languages</option>'
      +langs.map(function(l){return'<option value="'+esc(l)+'">'+esc(l)+'</option>';}).join("");
  }

  function buildCountryList(globalCount, withRoles, withoutRoles, counts, query) {
    var list = document.getElementById("im-country-list");
    if (!list) return;
    var q = query.toLowerCase().trim();
    var html = "";

    if (!q) {
      // "All countries" always first
      var allSel = selectedCountry === "" ? " selected" : "";
      html += '<div class="im-country-opt'+allSel+'" data-value="">All countries</div>';
      // "Global" pinned second if it has roles
      if (globalCount > 0) {
        var gSel = selectedCountry === "Global" ? " selected global" : " global";
        html += '<div class="im-country-opt'+gSel+'" data-value="Global">🌍 Global <span class="im-country-opt-badge">'+globalCount+'</span></div>';
        html += '<div class="im-country-divider">By country</div>';
      }
    }

    // Countries with roles
    var fWith = withRoles.filter(function(x){ return !q || x.toLowerCase().includes(q); });
    fWith.forEach(function(x){
      var sel = selectedCountry === x ? " selected" : "";
      html += '<div class="im-country-opt'+sel+'" data-value="'+esc(x)+'">'+esc(x)+'<span class="im-country-opt-badge">'+counts[x]+'</span></div>';
    });

    // Divider + countries without roles
    if (!q && withRoles.length > 0 && withoutRoles.length > 0) {
      html += '<div class="im-country-divider">Other countries</div>';
    }
    var fWithout = withoutRoles.filter(function(x){ return !q || x.toLowerCase().includes(q); });
    fWithout.forEach(function(x){
      var sel = selectedCountry === x ? " selected" : "";
      html += '<div class="im-country-opt muted'+sel+'" data-value="'+esc(x)+'">'+esc(x)+'</div>';
    });

    if (!fWith.length && !fWithout.length && q) {
      html += '<div class="im-country-opt muted" style="cursor:default;">No results</div>';
    }

    list.innerHTML = html;

    list.querySelectorAll(".im-country-opt[data-value]").forEach(function(opt){
      opt.addEventListener("click", function(){
        var val = this.getAttribute("data-value");
        selectedCountry = val;
        document.getElementById("im-country-label").textContent = val ? (val === "Global" ? "🌍 Global" : val) : "All countries";
        document.getElementById("im-country-trigger").classList.remove("open");
        document.getElementById("im-country-dropdown").style.display = "none";
        document.getElementById("im-country-search").value = "";
        var gc = countryCounts["Global"] || 0;
        var wr = ALL_COUNTRIES.filter(function(x){ return (countryCounts[x]||0)>0 && x!=="Global"; });
        var wo = ALL_COUNTRIES.filter(function(x){ return !countryCounts[x] && x!=="Global"; });
        buildCountryList(gc, wr, wo, countryCounts, "");
        refreshStateDropdown(val);
        applyFilters();
      });
    });
  }

  var selectedCountry = "";

  document.getElementById("im-country-trigger").addEventListener("click", function(e){
    e.stopPropagation();
    var dd = document.getElementById("im-country-dropdown");
    var open = dd.style.display !== "none";
    dd.style.display = open ? "none" : "block";
    this.classList.toggle("open", !open);
    if (!open) document.getElementById("im-country-search").focus();
  });

  document.getElementById("im-country-search").addEventListener("input", function(){
    var gc = countryCounts["Global"] || 0;
    var wr = ALL_COUNTRIES.filter(function(x){ return (countryCounts[x]||0)>0 && x!=="Global"; });
    var wo = ALL_COUNTRIES.filter(function(x){ return !countryCounts[x] && x!=="Global"; });
    buildCountryList(gc, wr, wo, countryCounts, this.value);
  });

  document.addEventListener("click", function(e){
    var wrap = document.getElementById("im-country-wrap");
    if (wrap && !wrap.contains(e.target)) {
      document.getElementById("im-country-dropdown").style.display = "none";
      document.getElementById("im-country-trigger").classList.remove("open");
    }
  });

  function refreshStateDropdown(country) {
    var stateSelect = document.getElementById("im-f-state");
    if (!country) {
      stateSelect.style.display = "none";
      stateSelect.innerHTML = '<option value="">All states</option>';
      return;
    }
    var stateMap = countryStateMap[country] || {};
    var states = Object.keys(stateMap).sort();
    if (!states.length) {
      stateSelect.style.display = "none";
      stateSelect.innerHTML = '<option value="">All states</option>';
      return;
    }
    stateSelect.style.display = "";
    stateSelect.innerHTML = '<option value="">All states</option>' + states.map(function(s){
      return '<option value="'+esc(s)+'">'+esc(s)+' ('+stateMap[s]+')</option>';
    }).join("");
  }

  function applyFilters() {
    var q       = document.getElementById("im-search").value.toLowerCase().trim();
    var dept    = document.getElementById("im-f-dept").value;
    var type    = document.getElementById("im-f-type").value.toLowerCase().trim();
    var country = selectedCountry;
    var state   = document.getElementById("im-f-state").value;
    var lang    = document.getElementById("im-f-lang").value.toLowerCase().trim();
    filteredJobs = allJobs.filter(function(j){
      var text = ((j.title||"")+" "+(j.department||"")+" "+(j.location||"")+" "+(j.country||"")+" "+(j.state||"")+" "+(j.description||"")+" "+(j.experience||"")+" "+(j.language||"")).toLowerCase();
      var jType = (j.type||"").toLowerCase().trim();
      var jLang = (j.language||"").toLowerCase();
      return (!q       || text.includes(q))
          && (!dept    || (j.department||"").trim()===dept)
          && (!type    || jType===type || (type==="independent contractor (scholar)" && (jType.includes("scholar")||jType.includes("independent"))))
          && (!country || (j.country||"").trim()===country)
          && (!state   || (j.state||"").trim()===state)
          && (!lang    || jLang.includes(lang));
    });
    loadedCount = 0;
    document.getElementById("im-jobs-container").innerHTML = "";
    loadNextBatch();
  }

  function loadNextBatch() {
    if (isLoading) return;
    if (filteredJobs.length - loadedCount <= 0 && loadedCount > 0) { updateLoadMore(false); return; }
    if (!filteredJobs.length) {
      document.getElementById("im-jobs-container").innerHTML =
        '<div class="im-empty">'
        +'<h3>No roles match your search</h3>'
        +'<p>There are currently no open roles for this location, but new opportunities are added regularly. Please check back soon or follow the <a href="https://www.linkedin.com/company/imerit-scholars" target="_blank" style="color:#531CB3;font-weight:500;">iMerit Scholars LinkedIn page</a> for the latest job updates.</p>'
        +'<p style="margin-top:12px;">You can also <a href="https://join-scholars.imerit.net/" target="_blank" style="color:#531CB3;font-weight:500;">register for iMerit Scholars</a> to be considered for future expert opportunities across languages, domains, and AI projects.</p>'
        +'</div>';
      updateLoadMore(false); updateCount(); return;
    }
    isLoading = true;
    updateLoadMore(true);
    setTimeout(function() {
      var batch = filteredJobs.slice(loadedCount, loadedCount + JOBS_PER_BATCH);
      loadedCount += batch.length;
      var container = document.getElementById("im-jobs-container");
      var grid = container.querySelector(".im-job-grid");
      if (!grid) { grid = document.createElement("div"); grid.className = "im-job-grid"; container.appendChild(grid); }
      batch.forEach(function(j){
        var expiry = formatExpiry(j.expiry_date);
        var card = document.createElement("div");
        card.className = "im-job-card";
        card.setAttribute("data-idx", allJobs.indexOf(j));
        card.innerHTML =
          '<div class="im-job-card-top">'
            +'<span class="im-type-badge '+badgeClass(j.type)+'">'+esc(j.type)+'</span>'
            +(expiry?'<span class="im-expiry">'+esc(expiry)+'</span>':'')
          +'</div>'
          +'<div class="im-job-title">'+esc(j.title)+'</div>'
          +'<div class="im-job-dept">'+esc(j.department)+'</div>'
          +'<div class="im-job-meta">'
            +'<span>📍 '+esc(j.location || [j.state, j.country].filter(Boolean).join(", "))+'</span>'
            +'<span>⏱ '+esc(j.experience)+'</span>'
            +(j.duration?'<span>📅 '+esc(j.duration)+'</span>':'')
            +(j.language?'<span>🌐 '+esc(j.language)+'</span>':'')
          +'</div>'
          +'<div class="im-job-desc">'+esc(j.description)+'</div>'
          +'<div class="im-view-btn">View role →</div>';
        card.addEventListener("click", function(){
          var idx = parseInt(this.getAttribute("data-idx"));
          var job = allJobs[idx];
          if (job) showDetail(job);
        });
        grid.appendChild(card);
      });
      isLoading = false;
      updateCount();
      updateLoadMore(filteredJobs.length > loadedCount);
      if (filteredJobs.length > loadedCount) {
        setTimeout(function() {
          var sentinel = document.getElementById("im-load-sentinel");
          if (sentinel) {
            var rect = sentinel.getBoundingClientRect();
            if (rect.top < window.innerHeight + 300) { loadNextBatch(); }
          }
        }, 650);
      }
    }, 600);
  }

  function updateCount() {
    document.getElementById("im-results-count").textContent =
      filteredJobs.length + " role" + (filteredJobs.length!==1?"s":"") + " found"
      + (loadedCount < filteredJobs.length ? " · showing " + loadedCount : "");
  }

  function updateLoadMore(hasMore) {
    document.getElementById("im-load-more-wrap").style.display = (hasMore || isLoading) ? "block" : "none";
  }

  if (window.IntersectionObserver) {
    var sentinel = document.getElementById("im-load-sentinel");
    var observer = new IntersectionObserver(function(entries){
      if (entries[0].isIntersecting && !isLoading) { loadNextBatch(); }
    }, { rootMargin: "300px" });
    observer.observe(sentinel);
  }

  function renderFeatured() {
    var featured = allJobs.filter(function(j){ return j.featured===true||j.featured==="true"||j.featured==="yes"; })[0];
    var el = document.getElementById("im-featured");
    if (!featured) { el.classList.remove("visible"); return; }
    document.getElementById("im-featured-title").textContent = featured.title;
    document.getElementById("im-featured-desc").textContent = featured.description || "";
    document.getElementById("im-featured-meta").innerHTML =
      '<span>📍 '+esc(featured.location)+'</span>'
      +'<span>🏢 '+esc(featured.department)+'</span>'
      +'<span>⏱ '+esc(featured.experience)+'</span>'
      +(featured.duration?'<span>📅 '+esc(featured.duration)+'</span>':'')
      +(featured.pay_rate?'<span>💰 '+esc(featured.pay_rate)+'</span>':'');
    var exp = formatExpiry(featured.expiry_date);
    document.getElementById("im-featured-expiry").textContent = exp ? "⏰ " + exp : "";
    el.classList.add("visible");
    el.addEventListener("click", function(){ showDetail(featured); });
  }

  function showDetail(job) {
    currentJob = job;
    // ── FIX: use job_id first for unique URLs ──
    var jobSlug = job.job_id || job.slug || job.title.toLowerCase().replace(/\s+/g,"-");
    history.pushState({ view:"detail", slug: jobSlug }, "", "?job=" + encodeURIComponent(jobSlug));
    document.getElementById("im-list").classList.add("hidden");
    document.getElementById("im-detail").classList.add("active");
    document.getElementById("im-jobs-root").scrollIntoView({ behavior: "smooth", block: "start" });
    var expiry = formatExpiry(job.expiry_date);
    document.getElementById("im-detail-hero").innerHTML =
      '<div class="im-detail-hero-top">'
        +'<div>'
          +'<span class="im-type-badge '+badgeClass(job.type)+'">'+esc(job.type)+'</span>'
          +'<h1>'+esc(job.title)+'</h1>'
          +'<div class="im-detail-hero-dept">'+esc(job.department)+'</div>'
        +'</div>'
        +'<button class="im-detail-apply-btn" id="im-hero-apply-btn">Apply Now →</button>'
      +'</div>'
      +'<div class="im-detail-pills">'
        +'<span class="im-detail-pill">📍 '+esc(job.location)+'</span>'
        +'<span class="im-detail-pill">⏱ '+esc(job.experience)+'</span>'
        +'<span class="im-detail-pill">🏢 '+esc(job.department)+'</span>'
        +(job.duration?'<span class="im-detail-pill">📅 '+esc(job.duration)+'</span>':'')
        +(job.language?'<span class="im-detail-pill">🌐 '+esc(job.language)+'</span>':'')
        +(job.pay_rate?'<span class="im-detail-pill">💰 '+esc(job.pay_rate)+'</span>':'')
        +(expiry?'<span class="im-detail-pill im-pill-warn">⏰ '+esc(expiry)+'</span>':'')
      +'</div>';
    document.getElementById("im-hero-apply-btn").addEventListener("click", function(){ applyNow(job); });
    document.getElementById("im-detail-content").innerHTML =
      section("About the role", job.about || job.description)
      + section("What you'll do", job.responsibilities && job.responsibilities.length ? job.responsibilities : null)
      + section("What we're looking for", job.requirements && job.requirements.length ? job.requirements : null)
      + section("Nice to have", job.nice_to_have && job.nice_to_have.length ? job.nice_to_have : null)
      + section("What we offer", job.benefits && job.benefits.length ? job.benefits : null);
    var videoHTML = "";
    if (job.video_url) {
      var vsrc = job.video_url;
      if (vsrc.indexOf("youtu.be/") > -1)             vsrc = "https://www.youtube.com/embed/" + vsrc.split("youtu.be/")[1].split("?")[0];
      else if (vsrc.indexOf("youtube.com/watch") > -1) vsrc = "https://www.youtube.com/embed/" + vsrc.split("v=")[1].split("&")[0];
      else if (vsrc.indexOf("vimeo.com/") > -1)        vsrc = "https://player.vimeo.com/video/" + vsrc.split("vimeo.com/")[1].split("?")[0];
      videoHTML = '<div class="im-sidebar-card" style="padding:0;overflow:hidden;"><div class="im-video-wrap" style="margin:0;border-radius:12px;"><iframe src="'+esc(vsrc)+'" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div></div>';
    }
    document.getElementById("im-detail-sidebar").innerHTML =
      videoHTML
      +'<div class="im-sidebar-card"><button class="im-sidebar-apply-btn" id="im-sidebar-apply-btn">Apply for this role →</button></div>'
      +'<div class="im-sidebar-card"><h3>Job details</h3>'
        +'<div class="im-sidebar-detail-item"><div class="lbl">Department</div><div class="val">'+esc(job.department)+'</div></div>'
        +'<div class="im-sidebar-detail-item"><div class="lbl">Location</div><div class="val">'+esc(job.location)+'</div></div>'
        +'<div class="im-sidebar-detail-item"><div class="lbl">Type</div><div class="val">'+esc(job.type)+'</div></div>'
        +'<div class="im-sidebar-detail-item"><div class="lbl">Experience</div><div class="val">'+esc(job.experience)+'</div></div>'
        +(job.duration?'<div class="im-sidebar-detail-item"><div class="lbl">Duration</div><div class="val">'+esc(job.duration)+'</div></div>':'')
        +(job.language?'<div class="im-sidebar-detail-item"><div class="lbl">Language</div><div class="val">'+esc(job.language)+'</div></div>':'')
        +(job.pay_rate?'<div class="im-sidebar-detail-item"><div class="lbl">Pay rate</div><div class="val">'+esc(job.pay_rate)+'</div></div>':'')
        +(expiry?'<div class="im-sidebar-detail-item"><div class="lbl" style="color:#ef4444;">Closing date</div><div class="val" style="color:#ef4444;">'+esc(expiry)+'</div></div>':'')
      +'</div>';
    document.getElementById("im-sidebar-apply-btn").addEventListener("click", function(){ applyNow(job); });
  }

  function goBackToList() {
    document.getElementById("im-detail").classList.remove("active");
    document.getElementById("im-list").classList.remove("hidden");
    currentJob = null;
    history.replaceState({}, "", window.location.pathname);
    document.getElementById("im-jobs-root").scrollIntoView({ behavior: "smooth", block: "start" });
  }

  document.getElementById("im-back-btn").addEventListener("click", function(){ history.back(); });
  window.addEventListener("popstate", function(){
    if (document.getElementById("im-detail").classList.contains("active")) goBackToList();
  });

  function applyNow(job) {
    var j = job || currentJob;
    var url;
    if (j && j.apply_link && j.apply_link.indexOf("mailto") === -1) url = j.apply_link;
    else if (GOOGLE_FORM_URL && GOOGLE_FORM_URL !== "YOUR_GOOGLE_FORM_URL_HERE") url = GOOGLE_FORM_URL;
    else if (j && j.apply_link) url = j.apply_link;
    else url = "mailto:careers@imerit.net";
    window.open(url, "_blank");
  }

  document.getElementById("im-search").addEventListener("input",  applyFilters);
  document.getElementById("im-f-dept").addEventListener("change", applyFilters);
  document.getElementById("im-f-type").addEventListener("change", applyFilters);
  document.getElementById("im-f-state").addEventListener("change", applyFilters);
  document.getElementById("im-f-lang").addEventListener("change", applyFilters);
  document.getElementById("im-clear-btn").addEventListener("click", function(){
    document.getElementById("im-search").value="";
    document.getElementById("im-f-dept").value="";
    document.getElementById("im-f-type").value="";
    selectedCountry = "";
    document.getElementById("im-country-label").textContent = "All countries";
    document.getElementById("im-country-search").value = "";
    var gc = countryCounts["Global"] || 0;
    var wr = ALL_COUNTRIES.filter(function(x){ return (countryCounts[x]||0)>0 && x!=="Global"; });
    var wo = ALL_COUNTRIES.filter(function(x){ return !countryCounts[x] && x!=="Global"; });
    buildCountryList(gc, wr, wo, countryCounts, "");
    refreshStateDropdown("");
    document.getElementById("im-f-lang").value="";
    applyFilters();
  });

  function initWithJobs(data) {
    allJobs = (data&&data.jobs) ? data.jobs : (Array.isArray(data)?data:[]);
    var ts = data&&data.generated_at ? new Date(data.generated_at).toLocaleString() : "";
    if (ts) document.getElementById("im-last-updated").textContent = "Last updated: "+ts;
    populateFilters();
    renderFeatured();
    filteredJobs = allJobs.slice();
    loadedCount = 0;
    document.getElementById("im-jobs-container").innerHTML = "";
    loadNextBatch();
    checkUrlParam();
  }

  function loadJobs() {
    if (!JOBS_FEED_URL || JOBS_FEED_URL==="YOUR_JOBS_FEED_URL_HERE") { initWithJobs({jobs:[]}); return; }
    fetch(JOBS_FEED_URL)
      .then(function(r){ return r.json(); })
      .then(function(data){ initWithJobs(data); })
      .catch(function(e){ console.warn("Jobs feed error:", e); initWithJobs({jobs:[]}); });
  }

  // ── FIX: 5-fallback URL matching so old URLs still work ──
  function checkUrlParam() {
    var params = new URLSearchParams(window.location.search);
    var jobParam = params.get("job");
    if (!jobParam) return;
    function makeSlug(str) {
      return (str||"").toLowerCase().replace(/[^a-z0-9\s-]/g,"").replace(/\s+/g,"-").replace(/-+/g,"-").replace(/^-|-$/g,"");
    }
    var job = allJobs.filter(function(j){
      if (j.job_id && j.job_id.toLowerCase() === jobParam.toLowerCase()) return true;
      if ((j.slug||"") === jobParam) return true;
      if (makeSlug(j.title) + (j.location ? "-" + makeSlug(j.location) : "") === jobParam) return true;
      if (makeSlug(j.title) + (j.country ? "-" + makeSlug(j.country) : "") === jobParam) return true;
      if (makeSlug(j.title) === jobParam) return true;
      return false;
    })[0];
    if (job) showDetail(job);
  }

  loadJobs();

})();
</script>				</div>
